    require(_value >= sC2C.minBet && _value <= sC2C.maxBet);
    require(chip.transferFrom(_from, manager, _value));

    uint256 amountWon = _value * (50 + uint256(keccak256(block.timestamp, block.difficulty, salt++)) % 100 - sC2C.houseEdge) / 100;
